export const awsChapters = chapters.map(chapter => {
  if (!walkthroughs[chapter.id]) return chapter;
  const summaryIndex = chapter.blocks.findIndex(block => block.text === '日本語総まとめ');
  return {...chapter,blocks:[...chapter.blocks.slice(0,summaryIndex),
    ...section('လက်တွေ့ဖြစ်ရပ်ကို အစမှအဆုံး လိုက်ကြည့်ခြင်း',...walkthroughs[chapter.id]),
    ...chapter.blocks.slice(summaryIndex)]};
});
